   241|  if (nextStatus && !VALID_STATUSES.includes(nextStatus as LedgerJobStatus)) {
   242|    return ownerOnlyJson({ ok: false, error: `Invalid status. Valid: ${VALID_STATUSES.join(', ')}` }, 400);
