   249|  if (!job) {
   250|    // Owner-approved job creation: body.create === true registers a NEW job
   251|    // so the ledger can track work discovered after the baseline. Requires
   252|    // an explicit worker, title and a valid JOB-xxxx id.
   253|    const wantsCreate = body.create === true;
   254|    const workerId = typeof body.workerId === 'string' ? body.workerId.trim().toUpperCase() : '';
   255|    const title = typeof body.title === 'string' ? body.title.trim().slice(0, 200) : '';
