AT=$(cat /tmp/owner_at); python3 - "$AT" <<'EOF'
import json, subprocess, sys, time
AT=sys.argv[1]
FILES=[
 ('backend/api/ivx-ia-orchestrator.ts','feat(ia): 12-IA orchestrator API — persistent roster/queue/locks/factory (owner mandate 2026-07-18)'),
 ('backend/api/ivx-auth-qa-scheduler.ts','feat(ia): include 12-IA operating summary in 2h consolidated owner-chat report'),
 ('backend/hono-extended.ts','feat(ia): register /api/ivx/autonomous/ia routes (status, task, lock)'),
]
for path,msg in FILES:
    content=open(path).read()
    body=json.dumps({
      'action':'github_commit_file','confirm':True,'confirmText':'CONFIRM_IVX_GITHUB_WRITE',
      'reason':'Owner mandate 2026-07-18: ACTIVATE IVX 12-IA OPERATING MODEL — deploy orchestrator API and 2h consolidated reporting.',
      'input':{'path':path,'content':content,'message':msg,'branch':'main'}
    })
    p=subprocess.run(['curl','-s','--max-time','55','-X','POST','-H',f'Authorization: Bearer {AT}','-H','Content-Type: application/json','--data-binary','@-','https://api.ivxholding.com/api/ivx/developer-deploy/action'],input=body,capture_output=True,text=True)
    try:
        d=json.loads(p.stdout)
        res=d.get('result') or d
        sha=(res.get('commit') or {}).get('sha') if isinstance(res.get('commit'),dict) else res.get('commitSha') or res.get('sha')
        print(f"{path} → ok={d.get('ok', d.get('status'))} sha={str(sha)[:12]}")
        if not sha: print('  raw:', p.stdout[:300])
    except Exception:
        print(f"{path} → RAW: {p.stdout[:300]}")
    time.sleep(2)
EOF

